(() => {
  'use strict';
  const S=window.QCServices;if(!S)return;
  const {config,root,$,$$,t,status,endpoint,api,notify}=S;
  const localPreview=['localhost','127.0.0.1'].includes(location.hostname);
  const mock=config.mock_slots&&(config.design_mode||localPreview);
  let cart=window.QCCart.get(),zones=[];
  try{zones=JSON.parse(config.zones||'[]');if(!Array.isArray(zones))zones=[];}catch{zones=[];}
  const slotsByForm=new WeakMap(),dateRequests=new WeakMap(),initialized=new WeakSet();
  let updating=Promise.resolve();
  const dateInDubai=instant=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(instant));const value=type=>parts.find(p=>p.type===type).value;return `${value('year')}-${value('month')}-${value('day')}`;};
  const tomorrow=()=>dateInDubai(Date.now()+86400000);
  const fingerprint=data=>data.items.map(item=>`${item.variant_id}:${item.quantity}:${item.selling_plan_allocation?.selling_plan.id||''}:${JSON.stringify(Object.fromEntries(Object.entries(item.properties||{}).sort()))}`).sort().join('|');
  function area(){const selected=$('[data-area]')?.value;if(selected)return selected;try{return localStorage.getItem('qc-dubai-area')||'';}catch{return '';}}
  function zoneMessage(){const selected=area();if(!selected)return t('select_area');if(!zones.length)return t('zone_unverified');return zones.some(z=>z?.active===true&&z.city==='Dubai'&&z.country==='AE'&&(z.label===selected||z.id===selected))?t('zone_supported'):t('zone_unsupported');}
  function syncZone(){const value=zoneMessage();$$('[data-zone-status]').forEach(el=>el.textContent=value);}
  function update(payload){
    const next=updating.catch(()=>{}).then(async()=>{const response=await fetch(root+'cart/update.js',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(t('error'));cart=data;return data;});updating=next;return next;
  }
  function clearReservation(){return {delivery_date:'',delivery_slot:'',delivery_reservation:'',delivery_reservation_expires:'',delivery_proof:'',delivery_cart_fingerprint:'',delivery_mock:''};}
  async function loadSlots(form){
    const input=$('[data-delivery-date]',form),select=$('[data-delivery-slot]',form),info=$('[data-slot-status]',form),date=input.value;
    const seq=(dateRequests.get(form)||0)+1;dateRequests.set(form,seq);
    select.replaceChildren(new Option(t('slot_choose'),''));select.disabled=true;
    if(!mock&&!config.endpoints.slots){info.textContent=t('slot_disconnected');return;}
    if(!date||date<tomorrow()){info.textContent=t('slot_none');return;}
    if(!area()){info.textContent=t('select_area');return;}
    info.textContent=t('loading');
    try{
      let slots;
      if(mock)slots=[{id:'preview-morning',label:'09:00–12:00',date,starts_at:date+'T09:00:00+04:00',remaining:2},{id:'preview-afternoon',label:'13:00–16:00',date,starts_at:date+'T13:00:00+04:00',remaining:0},{id:'preview-evening',label:'17:00–20:00',date,starts_at:date+'T17:00:00+04:00',remaining:1}];
      else{const url=endpoint('slots','slots');url.searchParams.set('date',date);url.searchParams.set('zone',area());const response=await fetch(url,{headers:{Accept:'application/json'},credentials:url.origin===location.origin?'same-origin':'omit'});if(!response.ok)throw new Error(t('error'));slots=(await response.json()).slots;}
      if(dateRequests.get(form)!==seq)return;
      slots=Array.isArray(slots)?slots.filter(slot=>typeof slot.id==='string'&&typeof slot.label==='string'&&slot.date===date&&Number.isSafeInteger(slot.remaining)&&slot.remaining>=0&&Number.isFinite(Date.parse(slot.starts_at))&&Date.parse(slot.starts_at)>Date.now()&&dateInDubai(slot.starts_at)===date):[];
      slotsByForm.set(form,slots);slots.forEach(slot=>{const option=new Option(slot.label+(slot.remaining===0?' · '+t('slot_full'):''),slot.id);option.disabled=slot.remaining===0;select.append(option);});
      select.disabled=!slots.some(s=>s.remaining>0);if(cart.attributes?.delivery_date===date&&slots.some(s=>s.id===cart.attributes.delivery_slot&&s.remaining>0))select.value=cart.attributes.delivery_slot;
      info.textContent=mock?t('slot_mock'):slots.some(s=>s.remaining>0)?t('area_note'):t('slot_none');
    }catch(error){if(dateRequests.get(form)===seq)info.textContent=error.message;}
  }
  function init(){
    syncZone();
    $$('[data-delivery-form]').forEach(form=>{if(initialized.has(form))return;initialized.add(form);const input=$('[data-delivery-date]',form);input.min=tomorrow();if(!input.value||input.value<input.min)input.value=input.min;if(config.endpoints.slots||mock)loadSlots(form);else input.disabled=true;});
    $$('[data-checkout-form]').forEach(form=>{const button=$('[name=checkout]',form);button.disabled=mock||cart.attributes?.delivery_mock==='true';if(button.disabled)status(form,t('slot_mock'));});
  }
  document.addEventListener('change',event=>{
    const target=event.target;
    if(target.matches('[data-delivery-date]'))loadSlots(target.closest('form'));
    if(target.matches('[data-area]')){
      syncZone();update({attributes:{...clearReservation(),delivery_zone:target.value}}).then(()=>window.QCCart.refresh()).catch(()=>notify(t('error')));
    }
  });
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('[data-delivery-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;form.setAttribute('aria-busy','true');
    try{
      const note=$('[name=note]',form).value;
      if(!mock&&!config.endpoints.slots){await update({note});await window.QCCart.refresh();notify(t('notes_saved'));return;}
      const date=$('[data-delivery-date]',form).value,id=$('[data-delivery-slot]',form).value,slot=(slotsByForm.get(form)||[]).find(s=>s.id===id&&s.remaining>0);
      if(!slot||date<tomorrow())throw new Error(t('slot_expired'));
      const current=await (await fetch(root+'cart.js',{headers:{Accept:'application/json'}})).json();
      let reservation;
      if(mock)reservation={reservation_id:'preview-only',expires_at:date+'T00:00:00+04:00',proof:'',cart_fingerprint:fingerprint(current)};
      else reservation=await api('slots','reservations',{slot_id:id,date,zone:area(),cart_token:current.token,items:current.items.map(i=>({id:i.variant_id,quantity:i.quantity})),idempotency_key:crypto.randomUUID()});
      if(!mock&&(reservation.ok!==true||typeof reservation.reservation_id!=='string'||typeof reservation.proof!=='string'||!reservation.proof||!Number.isFinite(Date.parse(reservation.expires_at))||Date.parse(reservation.expires_at)<=Date.now()||reservation.cart_fingerprint!==fingerprint(current)))throw new Error(t('slot_expired'));
      await update({note,attributes:{delivery_date:date,delivery_slot:id,delivery_zone:area(),delivery_reservation:reservation.reservation_id,delivery_reservation_expires:reservation.expires_at,delivery_proof:reservation.proof,delivery_cart_fingerprint:fingerprint(current),delivery_mock:mock?'true':''}});
      await window.QCCart.refresh();notify(mock?t('slot_mock'):t('slot_saved'));
    }catch(error){status(form,error.message);notify(error.message);}finally{form.removeAttribute('aria-busy');}
  });
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('[data-checkout-form]');if(!form||form.dataset.checkoutReady==='true')return;event.preventDefault();
    if(!$('[data-terms]',form).checked){status(form,t('terms_block'));return;}
    if(mock||cart.attributes?.delivery_mock==='true'){status(form,t('slot_mock'));return;}
    if(config.require_booking&&(!cart.attributes?.delivery_reservation||!cart.attributes?.delivery_proof||!Number.isFinite(Date.parse(cart.attributes.delivery_reservation_expires))||Date.parse(cart.attributes.delivery_reservation_expires)<=Date.now())){status(form,t('booking_required'));return;}
    const button=$('[name=checkout]',form);button.disabled=true;
    try{await update({attributes:{terms_accepted:'yes',terms_version:config.terms_version}});form.dataset.checkoutReady='true';button.disabled=false;form.requestSubmit(button);}catch(error){status(form,error.message);button.disabled=false;}
  });
  document.addEventListener('qc:cart-updated',event=>{
    cart=event.detail.cart;
    if(cart.attributes?.delivery_cart_fingerprint&&cart.attributes.delivery_cart_fingerprint!==fingerprint(cart)){
      update({attributes:clearReservation()}).then(()=>window.QCCart.refresh()).then(()=>notify(t('slot_changed'))).catch(()=>notify(t('error')));
    }
    init();
  });
  document.addEventListener('shopify:section:load',init);
  init();
})();

/* Homepage foundation: existing commerce palette and effective brand fonts. */
.qc-home{--qc-ink:var(--dc-forest);--qc-olive:var(--dc-olive);--qc-cream:var(--dc-cream);--qc-sand:var(--dc-sand);--qc-rust:var(--dc-rust);--qc-paper:var(--dc-paper);--qc-soft:color-mix(in srgb,var(--qc-ink) 4%,var(--qc-paper));--qc-line:color-mix(in srgb,var(--qc-ink) 15%,var(--qc-paper));--qc-muted:color-mix(in srgb,var(--qc-ink) 78%,var(--qc-paper));--qc-space-1:4px;--qc-space-2:8px;--qc-space-3:12px;--qc-space-4:16px;--qc-space-6:24px;--qc-space-8:32px;--qc-space-12:48px;--qc-radius:16px;--qc-radius-lg:28px;--qc-shadow:0 12px 40px color-mix(in srgb,var(--qc-ink) 10%,transparent);--qc-speed:220ms;--qc-ease:cubic-bezier(.2,.7,.3,1);color:var(--qc-ink);background:var(--qc-paper);font-family:var(--font-body-family);font-size:15px;line-height:1.5;letter-spacing:0}
.qc-home *{box-sizing:border-box}.qc-home [hidden]{display:none!important}.qc-home :is(button,input,select){font:inherit}.qc-home button{cursor:pointer}.qc-home button:disabled{cursor:not-allowed;opacity:.6}.qc-home :is(a,button,input,select,summary):focus-visible{outline:3px solid var(--qc-rust);outline-offset:4px}.qc-home a{color:inherit}.qc-home button{color:inherit}.qc-home :is(h1,h2,h3,p){margin-block-start:0}.qc-home h2{font-size:clamp(23px,2.4vw,32px);line-height:1.2;letter-spacing:-.04em}.qc-home h3{font-size:15px;line-height:1.4}.qc-wrap{width:min(1320px,calc(100% - 32px));margin-inline:auto}.qc-section{margin-block:40px}.qc-section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:20px;margin-block-end:20px}.qc-section-heading h2{margin:0}.qc-section-heading>a{font-size:13px;font-weight:700;white-space:nowrap;text-underline-offset:5px}.qc-section-intro{color:var(--qc-muted);margin-block-start:-8px}.qc-icon{flex-shrink:0;vertical-align:middle}.qc-button,.qc-add{display:inline-flex;align-items:center;justify-content:center;gap:16px;min-height:44px;border:1px solid var(--qc-ink);border-radius:10px;padding:10px 18px;background:var(--qc-ink);color:var(--qc-cream)!important;font-weight:700;text-decoration:none;transition:transform var(--qc-speed) var(--qc-ease),opacity var(--qc-speed)}.qc-button:hover{transform:translateY(-2px)}.qc-eyebrow{display:block;font-size:10px;font-weight:800;letter-spacing:.16em;margin-block-end:16px}.qc-muted{color:var(--qc-muted);font-size:13px}.qc-placeholder{display:block;width:100%;height:100%;fill:var(--qc-olive);background:var(--qc-soft)}.qc-empty{background:var(--qc-soft);padding:24px;border:1px dashed var(--qc-line);border-radius:var(--qc-radius);text-align:center;width:100%;grid-column:1/-1;flex:1}.qc-empty-art{width:100px;height:100px;margin:0 auto 16px}.qc-empty h3{font-size:19px}.qc-empty p{max-width:50ch;margin-inline:auto}.qc-text-link{display:inline-block;min-height:44px;padding-block:12px;font-weight:700;text-underline-offset:6px}
/* Announcement, compact sticky app header and search. */
.qc-announcement{background:var(--qc-ink);color:var(--qc-cream);font-size:12px;text-align:center}.qc-announcement>.qc-wrap{position:relative;min-height:36px;padding:8px 30px}.qc-announcement button{position:absolute;inset-inline-end:0;inset-block-start:0;border:0;background:none;color:inherit;min-width:44px;min-height:36px;font-size:20px}.qc-home .shopify-section:has(>.qc-header){position:sticky;inset-block-start:0;z-index:20}.qc-header{background:var(--qc-paper);border-bottom:1px solid var(--qc-line);transition:transform var(--qc-speed)}.qc-header.qc-scrolled{box-shadow:var(--qc-shadow)}.qc-header-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding-block:14px}.qc-logo{text-decoration:none;display:inline-flex;align-items:center;min-height:44px}.qc-wordmark{font-size:30px;letter-spacing:-2px;font-weight:850;white-space:nowrap}.qc-wordmark i{display:inline-block;width:7px;height:7px;margin-inline-start:4px;background:var(--qc-sand)}.qc-logo-image{object-fit:contain;width:140px;height:auto;max-height:60px}.qc-location{display:flex;align-items:center;gap:6px;margin-inline-start:auto;min-width:0}.qc-location small{display:block;font-size:10px;color:var(--qc-muted)}.qc-location select{max-width:155px;min-height:30px;font-size:12px;font-weight:700;background:none;color:var(--qc-ink);border:0;padding-inline:0}.qc-location>.qc-icon{width:18px}.qc-header-actions{display:flex;gap:10px}.qc-header-actions>a{min-width:44px;min-height:44px;display:flex;align-items:center;justify-content:center;text-decoration:none;position:relative}.qc-header-actions [data-cart-count]{position:absolute;inset-inline-end:-3px;inset-block-start:0;background:var(--qc-ink);color:var(--qc-cream);border-radius:20px;min-width:20px;text-align:center;font-size:11px}.qc-search{position:relative;display:flex;align-items:center;gap:12px;order:4;flex-basis:100%;border:1px solid var(--qc-line);border-radius:12px;background:var(--qc-soft);padding-inline:14px}.qc-search input{min-width:0;flex:1;border:0;background:none;color:var(--qc-ink);font-size:14px;min-height:48px}.qc-search input::placeholder{color:var(--qc-muted)}.qc-search>button{min-width:44px;min-height:44px;background:none;border:0;font-size:20px}.qc-suggestions{position:absolute;inset-block-start:calc(100% + 8px);inset-inline:0;z-index:25;border:1px solid var(--qc-line);padding:12px;background:var(--qc-paper);border-radius:14px;box-shadow:var(--qc-shadow);max-height:60vh;overflow:auto}.qc-suggestions a{display:flex;align-items:center;gap:14px;padding:8px;min-height:44px;text-decoration:none}.qc-suggestions a:hover,.qc-suggestions a:focus{background:var(--qc-soft)}.qc-suggestions img{width:48px;height:48px;object-fit:contain}.qc-search-loading{min-height:100px;background:linear-gradient(100deg,var(--qc-soft),var(--qc-paper),var(--qc-soft));background-size:200% 100%;animation:none}.qc-mobile-tabs{display:flex;position:fixed;inset-block-end:0;inset-inline:0;z-index:22;background:var(--qc-paper);border-top:1px solid var(--qc-line);padding:7px 8px calc(7px + env(safe-area-inset-bottom));justify-content:space-around}.qc-mobile-tabs a{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:60px;min-height:48px;position:relative;text-decoration:none;font-size:10px;gap:3px}.qc-mobile-tabs a[aria-current]{color:var(--qc-olive);font-weight:800}.qc-mobile-tabs [data-cart-count]{position:absolute;inset-block-start:0;inset-inline-end:5px;font-size:10px}
/* Editorial hero with a distinctive paper-bag illustration when no image is chosen. */
.qc-hero{position:relative;border-radius:var(--qc-radius-lg);background:var(--qc-cream);overflow:hidden;margin-block-start:20px}.qc-hero-slide{display:grid;grid-template-columns:1fr;min-height:460px}.qc-hero-copy{padding:32px 24px;position:relative;z-index:1;animation:qc-enter .6s var(--qc-ease)}.qc-hero h1{font-size:clamp(38px,5vw,66px);line-height:1.04;max-width:12ch;letter-spacing:-.055em;margin:0 0 20px}.qc-hero p{font-size:15px;max-width:41ch;color:var(--qc-muted);margin-block-end:24px}.qc-delivery-chip{display:flex;gap:8px;align-items:center;font-size:11px;margin-block-start:20px;font-weight:650}.qc-delivery-chip .qc-icon{width:19px}.qc-hero-art{position:relative;min-height:250px;display:grid;place-items:center;isolation:isolate}.qc-hero-art:before{content:'';position:absolute;z-index:-1;inset:0;border-radius:50% 50% 0 0;background:var(--qc-sand);opacity:.3;transform:translate(10%,12%)}.qc-hero-art>img{width:100%;height:100%;max-height:520px;object-fit:contain;animation:qc-float 7s ease-in-out infinite}.qc-hero-illustration{width:210px;height:230px;background:var(--qc-ink);color:var(--qc-cream);border-radius:15px 15px 40px 35px;display:flex;flex-direction:column;justify-content:center;align-items:center;padding:30px;text-align:center;transform:rotate(-8deg);box-shadow:12px 18px 0 color-mix(in srgb,var(--qc-olive) 18%,transparent);animation:qc-float 7s ease-in-out infinite}.qc-hero-illustration>.qc-icon{width:80px;height:80px;stroke-width:.8;margin-block-end:14px}.qc-hero-illustration>span{font-size:22px;line-height:1.1;letter-spacing:-.04em;font-weight:750}.qc-floating-badge{display:flex;gap:8px;align-items:center;position:absolute;inset-inline-end:12px;inset-block-end:20px;background:var(--qc-paper);box-shadow:var(--qc-shadow);border-radius:50px;padding:12px 16px;font-size:11px;font-weight:700;transform:rotate(4deg)}.qc-floating-badge .qc-icon{color:var(--qc-olive)}.qc-slide-controls{display:flex;gap:4px;position:absolute;inset-inline-end:16px;inset-block-start:12px;z-index:2}.qc-slide-controls button,.qc-rail-controls button{width:44px;height:44px;border:1px solid var(--qc-line);border-radius:50%;background:var(--qc-paper)}
/* Categories, compact product cards, and collection layouts. */
.qc-category-rail{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;padding-block:5px 12px;scrollbar-width:thin}.qc-category{flex:0 0 90px;text-align:center;text-decoration:none;scroll-snap-align:start;font-size:12px;line-height:1.3}.qc-category>span{display:block;aspect-ratio:1;background:var(--qc-soft);border-radius:24px;overflow:hidden;margin-block-end:12px;transition:transform var(--qc-speed)}.qc-category img{width:100%;height:100%;object-fit:contain}.qc-category:hover>span{transform:translateY(-4px)}.qc-steps{display:grid;gap:20px;border-block:1px solid var(--qc-line);padding-block:24px}.qc-steps article{display:flex;gap:16px;align-items:center}.qc-step-icon{position:relative;display:grid;place-items:center;min-width:54px;height:54px;border-radius:16px;background:var(--qc-cream)}.qc-step-icon>small{position:absolute;inset-inline-end:-5px;inset-block-start:-6px;background:var(--qc-ink);color:var(--qc-cream);border-radius:50%;width:22px;height:22px;text-align:center;font-size:9px;padding:4px}.qc-steps h2{font-size:16px;margin-block-end:3px}.qc-steps p{font-size:12px;margin:0;color:var(--qc-muted)}.qc-products{gap:12px}.qc-rail{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;padding:4px 2px 12px;scrollbar-width:thin}.qc-rail>.qc-card{flex:0 0 170px;scroll-snap-align:start}.qc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.qc-card{border:1px solid var(--qc-line);border-radius:var(--qc-radius);background:var(--qc-paper);overflow:hidden;min-width:0;transition:transform var(--qc-speed),box-shadow var(--qc-speed)}.qc-card:hover{transform:translateY(-4px);box-shadow:var(--qc-shadow)}.qc-card-image{display:block;position:relative;aspect-ratio:1;overflow:hidden;background:var(--qc-soft);padding:12px}.qc-card-image>img{width:100%;height:100%;object-fit:contain;transition:transform var(--qc-speed)}.qc-card:hover img{transform:scale(1.04)}.qc-discount{position:absolute;inset-inline-start:8px;inset-block-start:8px;background:var(--