{% doc %}Shared cart contents for page and drawer, refreshed through Section Rendering API.{% enddoc %}
<div data-cart-render><div class="qc-cart-items">{% for item in cart.items %}<article class="qc-cart-item">{% if item.image %}{{ item.image | image_url: width: 160 | image_tag: loading: 'lazy', widths: '80, 160', sizes: '80px' }}{% else %}{{ 'product-1' | placeholder_svg_tag: 'qc-placeholder' }}{% endif %}<div><a href="{{ item.url }}">{{ item.product.title | escape }}</a>{% unless item.product.has_only_default_variant %}<small>{{ item.variant.title | escape }}</small>{% endunless %}<strong>{{ item.final_line_price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong>{% for discount in item.line_level_discount_allocations %}<small>{{ discount.discount_application.title | escape }} (−{{ discount.amount | money_without_currency | prepend: ' ' | prepend: shop.currency }})</small>{% endfor %}<div class="qc-stepper"><button type="button" data-line-key="{{ item.key }}" data-quantity="{{ item.quantity | minus: 1 }}" aria-label="{{ 'qc.decrease' | t }}">−</button><span>{{ item.quantity }}</span><button type="button" data-line-key="{{ item.key }}" data-quantity="{{ item.quantity | plus: 1 }}" aria-label="{{ 'qc.increase' | t }}">+</button></div><button type="button" class="qc-remove" data-line-key="{{ item.key }}" data-quantity="0">{{ 'qc.remove' | t }}</button></div></article>{% else %}<div class="qc-empty">{% render 'qc-icon', name: 'bag' %}<h3>{{ 'qc.empty_cart' | t }}</h3><a href="{{ routes.all_products_collection_url }}" class="qc-button">{{ 'qc.continue' | t }}</a></div>{% endfor %}</div>
{% if cart.item_count > 0 %}{% assign lower = settings.qc_mid_threshold | default: 49 | times: 100 %}{% assign upper = settings.qc_free_delivery | default: 99 | times: 100 %}{% assign fee = settings.qc_fee_low | default: '5.99' | times: 100 | round %}{% if cart.total_price >= upper %}{% assign fee = 0 %}{% elsif cart.total_price >= lower %}{% assign fee = settings.qc_fee_mid | default: '3.99' | times: 100 | round %}{% endif %}
{% if upper > 0 %}{% assign progress = cart.total_price | times: 100.0 | divided_by: upper | at_most: 100 %}<div class="qc-free-delivery">{% if cart.total_price >= upper %}<p>{{ 'qc.free' | t }}</p>{% else %}{% assign remaining = upper | minus: cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency %}<p>{{ 'qc.until_free' | t: amount: remaining }}</p>{% endif %}<div class="qc-progress" role="progressbar" aria-label="{{ 'qc.free' | t }}" aria-valuenow="{{ progress | round }}" aria-valuemin="0" aria-valuemax="100"><span style="transform:scaleX({{ progress | divided_by: 100.0 }})"></span></div>{% if cart.total_price < lower %}{% assign next_remaining = lower | minus: cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency %}{% assign middle_fee = settings.qc_fee_mid | default: '3.99' | times: 100 | round | money_without_currency | prepend: ' ' | prepend: shop.currency %}<p>{{ 'qc.free_next_tier' | t: amount: next_remaining, fee: middle_fee }}</p>{% endif %}</div>{% endif %}
<div class="qc-cart-total"><span>{{ 'qc.subtotal' | t }}</span><strong>{{ cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong></div><div class="qc-cart-total qc-estimated-fee"><span>{{ 'qc.delivery_fee' | t }}</span><strong>{{ fee | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong></div>{% render 'qc-delivery-tiers' %}<p class="qc-muted">{{ settings.qc_vat_note | escape }}. {{ 'qc.delivery_note' | t }}</p>{% render 'qc-delivery-picker' %}<p class="qc-integration-note" data-zone-status></p>
<form action="{{ routes.cart_url }}" method="post" class="qc-checkout-form" data-checkout-form><label class="qc-checkout-terms"><input type="checkbox" name="attributes[terms_accepted]" value="yes" data-terms required><span>{{ 'qc.terms' | t }} <a href="{{ shop.terms_of_service.url | default: '/pages/terms-conditions' }}">{{ 'qc.terms_link' | t }}</a></span></label><p class="qc-terms-error" role="status"></p><button name="checkout" class="qc-button qc-checkout">{{ 'qc.checkout' | t }} ↗</button></form><div class="qc-policy-links">{% render 'qc-policy-links' %}</div>{% endif %}</div>

﻿{% doc %}Image-led category tile; artwork always comes from Shopify collections.
@param {object} category - Collection or navigation link object.
@param {string} title - Merchant category title.{% enddoc %}
{% assign category_image = category.image | default: category.featured_image %}
<span class="qc-category-art" aria-hidden="true">
  {% if category_image != blank %}
    {{ category_image | image_url: width: 160 | image_tag: loading: 'lazy', widths: '80, 160', sizes: '56px', alt: '' }}
  {% else %}{% render 'qc-icon', name: 'bag' %}{% endif %}
</span>
<span class="qc-category-name">{{ title | escape }}</span>

﻿{% doc %}Visible top-level categories with merchant-managed nested navigation.
@param {boolean} [mobile] - Render the full nested drawer navigation.{% enddoc %}
{% if mobile %}
  <nav class="qc-menu-tree" aria-label="{{ 'qc.categories' | t }}">
    {% for link in settings.qc_catalog_menu.links %}
      {% if link.links != blank %}
        <details><summary>{{ link.title | escape }}</summary><div class="qc-mega-panel">
          <a href="{{ link.url }}">{{ 'qc.view_all' | t }} {{ link.title | escape }}</a>
          {% for child in link.links %}<div><a href="{{ child.url }}">{{ child.title | escape }}</a>
            {% if child.links != blank %}<ul role="list">{% for leaf in child.links %}<li><a href="{{ leaf.url }}">{{ leaf.title | escape }}</a></li>{% endfor %}</ul>{% endif %}
          </div>{% endfor %}
        </div></details>
      {% else %}<a href="{{ link.url }}">{{ link.title | escape }}</a>{% endif %}
    {% else %}
      {% for collection in collections %}<a href="{{ collection.url }}">{{ collection.title | escape }}</a>
      {% else %}<a href="{{ routes.all_products_collection_url }}">{{ 'qc.view_all' | t }}</a>{% endfor %}
    {% endfor %}
  </nav>
{% else %}
  <nav class="qc-top-categories" aria-label="{{ 'qc.categories' | t }}">
    <a class="qc-category-explore" href="{{ routes.all_products_collection_url }}">
      {% render 'qc-icon', name: 'grid' %}<span>{{ 'qc.choose_products' | t }}</span><span aria-hidden="true">&#8599;</span>
    </a>
    <div class="qc-category-items">
      {% for link in settings.qc_catalog_menu.links %}
        {% if link.links != blank %}
          <details class="qc-category-node">
            <summary>{% render 'qc-category-label', category: link.object, title: link.title %}<span class="qc-category-chevron" aria-hidden="true">&#8964;</span></summary>
            <div class="qc-category-submenu">
              <a class="qc-category-submenu-title" href="{{ link.url }}">{{ 'qc.view_all' | t }} {{ link.title | escape }} <span aria-hidden="true">&#8599;</span></a>
              <div class="qc-category-submenu-grid">
                {% for child in link.links %}<div><a href="{{ child.url }}"><strong>{{ child.title | escape }}</strong></a>
                  {% if child.links != blank %}<ul role="list">{% for leaf in child.links %}<li><a href="{{ leaf.url }}">{{ leaf.title | escape }}</a></li>{% endfor %}</ul>{% endif %}
                </div>{% endfor %}
              </div>
            </div>
          </details>
          <a class="qc-category-tile qc-category-mobile" href="{{ link.url }}">{% render 'qc-category-label', category: link.object, title: link.title %}</a>
        {% else %}
          <a class="qc-category-tile" href="{{ link.url }}"{% if link.current %} aria-current="page"{% endif %}>{% render 'qc-category-label', category: link.object, title: link.title %}</a>
        {% endif %}
      {% else %}
        {% for collection in collections %}<a class="qc-category-tile" href="{{ collection.url }}">{% render 'qc-category-label', category: collection, title: collection.title %}</a>
        {% else %}<a class="qc-category-tile" href="{{ routes.all_products_collection_url }}">{% assign category_title = 'qc.categories' | t %}{% render 'qc-category-label', title: category_title %}</a>{% endfor %}
      {% endfor %}
    </div>
  </nav>
{% endif %}

{% doc %}@param {product} product - Real Shopify product.{% enddoc %}
{% if product.available or product.metafields.custom.show_when_sold_out.value == true %}
{% assign variant = product.selected_or_first_available_variant %}
<article class="qc-card" data-product-id="{{ product.id }}" data-product-handle="{{ product.handle | escape }}" data-variant-id="{{ variant.id }}"><a class="qc-card-image" href="{{ product.url }}" aria-label="{{ product.title | escape }}">{% if product.featured_image %}{{ product.featured_image | image_url: width: 1000 | image_tag: loading: 'lazy', widths: '180, 360, 540, 750, 1000', sizes: '(min-width: 990px) 200px, 44vw' }}{% else %}{{ 'product-1' | placeholder_svg_tag: 'qc-placeholder' }}{% endif %}{% if variant.compare_at_price > variant.price %}{% assign discount = variant.compare_at_price | minus: variant.price | times: 100.0 | divided_by: variant.compare_at_price | round %}<span class="qc-discount">{{ discount }}% {{ 'qc.off' | t }}</span>{% endif %}</a><div class="qc-card-tools"><button type="button" data-wishlist="{{ product.handle | escape }}" aria-label="{{ 'qc.wishlist' | t }}" aria-pressed="false">♡</button><label><input type="checkbox" data-compare="{{ product.handle | escape }}">{{ 'qc.compare' | t }}</label></div><div class="qc-card-copy"><h3><a href="{{ product.url }}">{{ product.title | escape }}</a></h3><p class="qc-card-size">{% if product.metafields.custom.pack_size.value != blank %}{{ product.metafields.custom.pack_size.value | escape }}{% elsif variant.weight > 0 %}{{ variant.weight | weight_with_unit }}{% elsif product.has_only_default_variant == false %}{{ variant.title | escape }}{% endif %}</p><div class="qc-card-bottom"><div class="qc-price"><strong>{{ variant.price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong>{% if variant.compare_at_price > variant.price %}<s>{{ variant.compare_at_price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</s>{% endif %}</div><div data-card-controls>{% if product.available %}<button class="qc-add" type="button" data-add{% if product.variants.size > 1 %} data-choose{% endif %}>{% if product.variants.size == 1 %}{{ 'qc.add' | t }} +{% else %}{{ 'qc.choose' | t }}{% endif %}</button>{% else %}<button class="qc-add" disabled>{{ 'qc.out' | t }}</button>{% endif %}</div></div></div>{% if product.variants.size > 1 %}<template data-variants><div data-quick-product-url="{{ product.url }}"><p>{{ 'qc.loading' | t }}</p><a class="qc-text-link" href="{{ product.url }}">{{ 'qc.variant_more' | t }}</a></div></template>{% endif %}{% unless product.available %}{% render 'qc-restock', product: product %}{% endunless %}</article>
{% endif %}

{% doc %}@param {collection} collection - Source collection.
@param {number} limit - Maximum visible products.{% enddoc %}
{% assign shown = 0 %}{% if collection != blank %}{% for product in collection.products limit: 50 %}{% if product.available or product.metafields.custom.show_when_sold_out.value == true %}{% render 'qc-product-card', product: product %}{% assign shown = shown | plus: 1 %}{% if shown >= limit %}{% break %}{% endif %}{% endif %}{% endfor %}{% endif %}{% if shown == 0 %}<div class="qc-empty"><div class="qc-empty-art">{{ 'product-1' | placeholder_svg_tag: 'qc-placeholder' }}</div><h3>{{ 'qc.empty_collection' | t }}</h3>{% if request.design_mode %}<p>{{ 'qc.empty_hint' | t }}</p>{% endif %}</div>{% endif %}

